const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define geometries and time
  const hotelDeVille = ee.Geometry.Point([2.3522, 48.8566]).buffer(500); // Paris center
  const faussesReposes = ee.Geometry.Point([2.17, 48.83]).buffer(1000); // Forest near Versailles

  // August 6, 2024 at 13:40 Paris time = 11:40 UTC (summer time)
  const date = '2024-08-06';
  const startTime = '2024-08-06T11:20:00'; // ±20 min window
  const endTime = '2024-08-06T12:00:00';

  // 2. Use MODIS Aqua LST (daily product, ~1:30pm overpass)
  const collection = ee.ImageCollection('MODIS/061/MYD11A1')
    .filterDate(startTime, endTime)
    .select('LST_Day_1km', 'QC_Day')
    .filterBounds(ee.FeatureCollection([hotelDeVille, faussesReposes]));

  // Check if collection is empty
  const count = collection.size().getInfo();
  if (count === 0) {
    print('No MODIS Aqua images found.');
    print('<answer>C1</answer>');
    return;
  }

  // Get the single image for the day
  const image = collection.first();

  // 3. Apply quality masking
  // Extract QC bits 0-1: 00 = good quality
  const qcMask = image.select('QC_Day').bitwiseAnd(3).eq(0);
  const lst = image.select('LST_Day_1km')
    .updateMask(qcMask)
    .multiply(0.02) // Convert to Kelvin
    .subtract(273.15); // Convert to Celsius

  // 4. Extract values for both locations
  const reduceParams = {
    reducer: ee.Reducer.mean(),
    geometry: null,
    scale: 1000,
    maxPixels: 1e9
  };

  const hotelStats = lst.reduceRegion({
    ...reduceParams,
    geometry: hotelDeVille
  });

  const forestStats = lst.reduceRegion({
    ...reduceParams,
    geometry: faussesReposes
  });

  const hotelTemp = hotelStats.get('LST_Day_1km').getInfo();
  const forestTemp = forestStats.get('LST_Day_1km').getInfo();

  // 5. Check for valid pixels
  const hotelCount = lst.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: hotelDeVille,
    scale: 1000,
    maxPixels: 1e9
  }).get('LST_Day_1km').getInfo();

  const forestCount = lst.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: faussesReposes,
    scale: 1000,
    maxPixels: 1e9
  }).get('LST_Day_1km').getInfo();

  print(`Images: ${count}, Hotel pixels: ${hotelCount}, Forest pixels: ${forestCount}`);

  // 6. Validate and determine answer
  if (hotelCount === 0 || forestCount === 0) {
    print('<answer>C2</answer>');
    return;
  }

  if (hotelTemp === null || forestTemp === null || 
      Math.abs(hotelTemp) > 60 || Math.abs(forestTemp) > 60) {
    print(`Invalid temps: Hotel ${hotelTemp}°C, Forest ${forestTemp}°C`);
    print('<answer>C3</answer>');
    return;
  }

  print(`Hotel temp: ${hotelTemp.toFixed(1)}°C, Forest temp: ${forestTemp.toFixed(1)}°C`);

  // 7. Final comparison
  if (hotelTemp < forestTemp) {
    print('<answer>A</answer>');
  } else {
    print('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
